UPDATE conversation
SET last_message_preview = #{content}, last_message_at = #{now}, updated_at = #{now}
WHERE id = #{conversationId}

mapper.select:
SELECT COUNT(*) FROM appointment
WHERE ${ownerColumn} = #{userId}

    AND status = #{status}

SELECT a.id, a.listing_id AS listingId, l.title AS listingTitle, a.tenant_id AS tenantId, t.nickname AS tenantName,
       a.agent_id AS agentId, a.scheduled_at AS scheduledAt, a.contact_name AS contactName, a.contact_mobile AS contactMobile,
       a.note, a.status, a.reject_reason AS rejectReason, a.created_at AS createdAt
FROM appointment a
JOIN house_listing l ON l.id = a.listing_id
JOIN sys_user t ON t.id = a.tenant_id
WHERE a.${ownerColumn} = #{userId}

    AND a.status = #{status}

ORDER BY a.scheduled_at DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE appointment
SET status = #{status}, reject_reason = #{reason}, updated_at = #{now}
WHERE id = #{id}
